const toURL = (url) => {
  if (!url) return null;
  try {
    return new URL(url);
  } catch {
    return null;
  }
};

// Extract recall_title - this is for listing page card title, not detail page
// Since we're on the detail page, this would be null (no listing card here)
let recall_title = null;

// Extract recall_url - URL from listing page card
// Since we're on the detail page, this would be null
let recall_url = null;

// Extract title_on_detail - Main h1 heading on detail page
let title_on_detail = $('h1').text_sane();

// Extract date_published - Publication date if shown
// Looking for date elements, but none found in the HTML
let date_published = null;

// Extract description - Main recall description from first text section
let description = $('[data-pub-type="text"]').first().text_sane();

// Extract product_name - Product names from h2 headings in container sections
let product_names = $('[data-pub-type="container"] h2').toArray()
  .map(el => $(el).text_sane())
  .filter(text => text && !text.includes('Refund') && !text.includes('See more'));
let product_name = product_names.join(', ') || null;

// Extract hazard - Safety risk described in the recall
let hazard_text = $('[data-pub-type="text"] p').first().text_sane();
let hazard = null;
if (hazard_text && hazard_text.includes('tip-over')) {
  hazard = 'tip-over accidents';
}

// Extract remedy - What customers should do
let remedy_parts = [];
// From button labels
$('[data-pub-type="button-link"] .pub__btn__label').toArray().forEach(el => {
  let text = $(el).text_sane();
  if (text) remedy_parts.push(text);
});
// From strong text in text sections
$('[data-pub-type="text"] strong').toArray().forEach(el => {
  let text = $(el).text_sane();
  if (text && !text.includes('Please note')) remedy_parts.push(text);
});
let remedy = remedy_parts.length > 0 ? remedy_parts.join(', ') : null;

// Extract image_urls - Product images from image-with-caption sections
let image_urls = $('[data-pub-type="image-with-caption"] img').toArray()
  .map(el => {
    let src = $(el).attr('src');
    if (src) {
      // Remove query parameters to get clean URL
      src = src.split('?')[0];
      return toURL(src);
    }
    return null;
  })
  .filter(url => url !== null);

// Extract recall_details_url - Link to CPSC page
let recall_details_url = toURL($('a[href*="cpsc.gov"]').attr('href'));

// Extract product_page_url - The input URL
let product_page_url = toURL(input.url);

return {
  recall_title,
  recall_url,
  title_on_detail,
  date_published,
  description,
  product_name,
  hazard,
  remedy,
  image_urls,
  recall_details_url,
  product_page_url
};
