if (match) {
  hazard = match[1].trim();
}
if (!hazard) {
  match = description.match(/risk of ([^.]+)/i);
  if (match) {
    hazard = match[1].trim();
  }
}
if (!hazard) {
  match = description.match(/can cause ([^.]+)/i);
  if (match) {
    hazard = match[1].trim();
