// Select all recall links from the content cards
const recall_links = $('.pub__content-card a[href*="/recalls/"]').toArray();

// Extract URLs and convert relative URLs to absolute
const base_url = 'https://www.ikea.com';
const recall_urls = recall_links.map(link => {
    const href = $(link).attr('href');
    if (href) {
        // Convert relative URLs to absolute URLs
        return new URL(href, base_url).href;
    }
}).filter(Boolean); // Remove any undefined/null values

// Remove duplicates
const unique_recall_urls = [...new Set(recall_urls)];

console.log(`Found ${unique_recall_urls.length} unique recall URLs`);

return {recall_urls: unique_recall_urls};

