const recalls = recall_cards.map(card => {
    const $card = $(card);

    // Extract title from h2 heading
    const recall_title = $card.find('h2').text_sane();

    // Extract URL from the link
    const href = $card.find('a').attr('href');
    const recall_url = href ? new URL(href, 'https://www.ikea.com').href : null;

    // Date is not visible on the listing page cards, set to null
    const date_published = null;

    return {
        recall_title,
        recall_url,
        date_published
    };
}).filter(recall => recall.recall_url); // Remove any entries without a URL

console.log(`Found ${recalls.length} recalls`);

return {recalls};

